  ('conference-2025-07', 'conference', '{}'::jsonb, '{"fr":"Conférence - Juillet 2025"}'::jsonb, '{}'::jsonb, '{}'::jsonb, '2025-07-01', 'Alain Lorang', 'fr', '/conferences/conference-2025-07.pdf', 1731221, null, null, '["immobilier","fiscalite"]'::jsonb, 20, 'veroeffentlicht'),
  ('domiciliation-atad-3', 'conference', '{}'::jsonb, '{"fr":"Domiciliation au Luxembourg : les défis à résoudre avant l’implémentation d’ATAD 3"}'::jsonb, '{}'::jsonb, '{}'::jsonb, '2023-03-01', 'Alain Lorang', 'fr', '/conferences/domiciliation-luxembourg.pdf', 157510, null, null, '["societes","fiscalite"]'::jsonb, 21, 'entwurf'),
  ('sci-conformite', 'conference', '{}'::jsonb, '{"fr":"SCI : COMMENT LES UTILISER EN TOUTE CONFORMITÉ ?!"}'::jsonb, '{"fr":"Nos experts feront le point sur la manière de créer et de gérer ces sociétés ainsi que sur la manière de les utiliser pour vos clients. Votre participation à cette conférence vous permettra de rencontrer notamment des fiduciaires, des conseillers fiscaux et des responsables bancaires ..."}'::jsonb, '{}'::jsonb, null, 'Alain Lorang', 'fr', null, null, null, 'https://www.finixevents.com/events/sci-2021', '["immobilier","societes"]'::jsonb, 22, 'entwurf'),
  ('investissement-immobilier-cles-juridiques', 'conference', '{}'::jsonb, '{"fr":"Investissement Immobilier au Luxembourg - Toutes les clés juridiques pour le conduire au mieux !"}'::jsonb, '{"fr":"L’investissement dans l’immobilier demeure l’un des plus fructueux. Le développement du secteur immobilier du Luxembourg est en expansion telle qu’un retour sur investissement devrait être assez rapide pour les investisseurs."}'::jsonb, '{}'::jsonb, null, 'Alain Lorang', 'fr', null, null, null, 'https://www.ifebenelux.lu/formation/investissement-immobilier-au-luxembourg', '["immobilier"]'::jsonb, 23, 'entwurf')
insert into public.team (id, titre_civil, nom, fonction, bio, barreau_depuis, photo, ordre, statut) values
  ('alain-lorang', 'Me', 'Alain Lorang', '{"fr":"Avocat à la Cour","en":"Lawyer"}'::jsonb, '{"fr":"<p>Diplômé de la faculté de Droit et des Sciences Economiques de Paris II (ASSAS), Maître Lorang obtient une maîtrise en droit des Affaires (Promotion 1980) et intègre ensuite l’Institut d’Etudes Politiques de Paris (Section Economique et Financière) où il sort diplômé en 1981.</p>\n<p>Il obtient le certificat du Ministère de l’Education Nationale Luxembourgeoise en Fiscalité en 1985 et le certificat du Centre de Formation Professionnelle des Avocats d’Alsace le 13 Novembre 1990.</p>\n<p>Maître Lorang est avocat au Barreau de Luxembourg depuis 1982. Il est également expert-judiciaire auprès de la Cour d’Appel de Luxembourg, ancien secrétaire du Conseil de l’Ordre du Barreau de Luxembourg et enfin membre du Conseil d’Administration et Trésorier de l’Observatoire Luxembourgeois de Droit Européen.</p>","en":"<p>A graduate of the Faculty of Law and Economics at the University of Paris II (Sorbonne-Assas), Alain Lorang obtained a master’s degree in Business Law (Class of 1980). He then studied at the Institut d’Etudes Politiques de Paris (Economic and Financial Department) and graduated in 1981.</p>\n<p>He obtained the certificate from the Luxembourg Ministry of National Education in Taxation Law in 1985 and the certificate from the French Center for Professional Training of Lawyers in Strasbourg on November 13, 1990.</p>\n<p>Alain Lorang has been a lawyer at the Luxembourg Bar since 1982. He is also a sworn legal expert at the Luxembourg Court of Appeal. He is a former secretary of the Council of the Luxembourg Bar Association and finally a member of the Board of Directors and Treasurer of the Luxembourg Observatory of European Law. (OLDE)</p>"}'::jsonb, 1982, 'portrait', 1, 'veroeffentlicht'),
  ('stephane-pelzer', 'Me', 'Stéphane Pelzer', '{"fr":"Avocat à la Cour","en":"Lawyer"}'::jsonb, '{"fr":"<p>Me Stéphane Pelzer, avocat à la cour, spécialisé en droit des étrangers, droit international, droit de l’environnement, droit public. Son expertise couvre un large éventail de problématiques juridiques, allant de l’accompagnement des particuliers dans des démarches administratives complexes à la représentation devant les juridictions nationales et internationales.</p>\n<p>Titulaire d’un Doctorat en droit public-droit de l’environnement de l’Université de Lorraine, Me Pelzer s’est consacré à l’étude approfondie des relations entre le droit et les grands enjeux sociétaux, notamment en matière de responsabilité environnementale et de régulation juridique. Sa formation universitaire, couplée à une solide expérience professionnelle, lui permet d’adopter une approche analytique et stratégique dans la défense des intérêts de ses clients.</p>\n<p>Tout au long de son parcours, il a acquis une expérience précieuse dans l’interprétation et l’application des normes juridiques, notamment dans des dossiers impliquant des questions de droit des étrangers, de contentieux administratifs et de réglementation européenne. Son engagement académique en tant qu’enseignant en droit public lui a également permis de développer une approche pédagogique du droit, garantissant à ses clients une compréhension claire et précise des enjeux liés à leurs affaires.</p>\n<p>Me Pelzer se distingue par son sens du détail, sa rigueur juridique et son engagement profond dans la défense des droits et libertés. Sa capacité d’analyse et son expertise en droit public font de lui un interlocuteur privilégié pour toute question juridique nécessitant une approche stratégique et personnalisée.</p>","en":"<p>Stéphane Pelzer is a lawyer specialising in immigration law, international law, environmental law and public law. His expertise covers a wide range of legal issues, from assisting individuals with complex administrative procedures to representing them before national and international courts.</p>\n<p>With a doctorate in public law and environmental law from the University of Lorraine, Mr Pelzer has devoted himself to an in-depth study of the relationship between the law and major societal issues, particularly in the areas of environmental liability and legal regulation. His university training, coupled with solid professional experience, enables him to adopt an analytical and strategic approach to defending his clients'' interests.</p>\n<p>Throughout his career, he has gained valuable experience in the interpretation and application of legal standards, particularly in cases involving issues of immigration law, administrative litigation and European regulations. His academic commitment as a lecturer in public law has also enabled him to develop a pedagogical approach to the law, ensuring that his clients have a clear and precise understanding of the issues involved in their cases.</p>\n<p>Mr Pelzer stands out for his attention to detail, his legal rigour and his deep commitment to defending rights and freedoms. His ability to analyse and his expertise in public law make him the ideal partner for any legal issue requiring a strategic and personalised approach.</p>"}'::jsonb, null, null, 2, 'entwurf')
insert into public.legal_pages (id, titre, chapeau, blocs, corps, statut) values
  ('mentions', '{"fr":"Mentions légales Étude d’Avocats LW LEGIS"}'::jsonb, '{}'::jsonb, '[]'::jsonb, '{"fr":"\n<h2>Immatriculation</h2>\n<p><strong>Raison sociale</strong> : Étude d’Avocats LW LEGIS<br><strong>Adresse siège social</strong> : 41 Avenue du X septembre B.P. 1734 LUXEMBOURG<br><strong>Responsable</strong> : Lorang</p>\n<h2>Contact</h2>\n<p><strong>Lorang</strong><br><strong>Téléphone</strong> : +352 44 71 76 22<br><strong>Adresse électronique</strong> : contact@cabinet-avocats-lorang.com<br><strong>Directeur de publication</strong> : Lorang</p>\n<h2>Hébergement du site web</h2>\n<p>Le site web cabinet-avocats-lorang.com utilise les services d’hébergement de 1&amp;1 Internet SARL.</p>\n<p>1&amp;1 Internet SARL<br>7 place de la Gare<br>BP 70109<br>RCS Sarreguemines B 431 303 775<br>SIRET 431 303 775 000 16<br>Code APE: 6201Z<br>Identification intracommunautaire FR 13 431303775<br>Téléphone : 0970 808 911</p>\n<h2>Droits d’auteur</h2>\n<p>Ce site est protégé par la législation française et internationale sur les droits d’auteurs et les propriétés intellectuelles. L’ensemble du contenu rédactionnel (données informatives, documents proposés en téléchargement, etc…) mais aussi graphique (image, animations et photographie) est protégé par copyright.</p>\n<p>Vous pouvez néanmoins utiliser des textes ou des fragments de contenu textuel sur support papier à condition de citer clairement et lisiblement la source du document, en précisant l’adresse URL de la page ou des pages citées (ex.” les extraits ci-dessus / ci-dessous proviennent du site http://www.xxxx.xx et sont protégés par les lois du copyright”). Le contenu cité ne doit en aucun cas être modifié, ni altéré et doit être conforme au contenu original du site internet. Le contenu cité ne peut en aucun cas faire l’objet de commercialisation ou de ventes, mais se doit d’être diffusé gratuitement et uniquement à des fins pédagogiques. Pour toutes questions relatives aux éventuelles citations puisées à partir de ce site vous pouvez nous écrire à contact@cabinet-avocats-lorang.com</p>\n<h2>Crédits photographique</h2>\n<p>L’ensemble des photographies utilisées sur ce site internet fait l’objet de droits d’utilisation stricts. La société 57informatique ayant développé le site web cabinet-avocats-lorang.com ne pourra pas être tenu responsable des photos présentes sur le site car celle-ci ayant été validées par le responsable de la société Étude d’Avocats LW LEGIS, Lorang.</p>\n<h2>Avis de non responsabilités</h2>\n<p>Ce site web peut contenir des liens hypertextes avec des sites web de parties tierces. Ceux-ci sont uniquement reproduits à titre d’information à l’utilisateur. Étude d’Avocats LW LEGIS n’a pas de contrôle sur le contenu de ces sites web et ne peut en aucun cas être tenu pour responsable de l’existence de ces sites web, ni de l’information qui y est contenue. En outre, l’existence de ces liens ne signifie pas que Étude d’Avocats LW LEGIS approuve le contenu de ces site web, ni qu’elle collabore de quelque façon que ce soit avec les exploitants de ces sites web.</p>\n<h2>Responsable de la publication</h2>\n<p>Le responsable de la société Étude d’Avocats LW LEGIS, Lorang.</p>\n<h2>Contact</h2>\n<p>Pour nous écrire :</p>\n<p>Étude d’Avocats LW LEGIS<br>41 Avenue du X septembre<br>L-2551 Luxembourg<br>Email : contact@cabinet-avocats-lorang.com<br>Téléphone : +352 44 71 76 22</p>\n"}'::jsonb, 'veroeffentlicht'),
  ('donnees', '{"fr":"Protection à l’égard du traitement des données personnelles"}'::jsonb, '{}'::jsonb, '[]'::jsonb, '{"fr":"\n<h2>ARTICLE 1er - INFORMATIONS GENERALES</h2>\n<p><strong>1.1</strong> Le site internet de Étude d’Avocats LW LEGIS est au service de la Société Étude d’Avocats LW LEGIS, au capital de €, ayant pour , dont le siège social est situé 41 Avenue du X septembre, L-2551 Luxembourg, représentée par Lorang, Responsable.</p>\n<p><strong>1.2</strong> Le responsable de traitement est la personne en charge d’un ou de plusieurs traitements de données à caractère personnel dont il détermine les finalités et les moyens. La Direction de Étude d’Avocats LW LEGIS est responsable du traitement de vos données personnelles dans le cadre de la présente politique.</p>\n<p><strong>1.3</strong> Le traitement aura comme finalités la possibilité pour l’utilisateur du site internet cabinet-avocats-lorang.com de bénéficier des différentes offres et services proposés sur le site, mais également par exemple, d’obtenir la livraison des biens commandés à l’adresse de livraison.</p>\n<p>Le traitement des données personnelles est donc une condition nécessaire à la bonne exécution de la demande. La non-fourniture de ces données ne permettrait donc pas de bénéficier des différentes offres, et ne permettrait pas aux biens d’être livrés.</p>\n<p>Plus spécialement, Nous demandons des Données Personnelles lorsque vous vous inscrivez pour recevoir des informations concernant nos services, des offres spéciales, des événements et des mises à jour de nos produits.</p>\n<p>Les Données Personnelles que nous vous demandons comprennent vos nom, prénom, adresse, numéro de téléphone, adresse électronique, sexe.</p>\n<p>Lorsque vous visitez notre Site Internet, nous recueillons automatiquement les informations suivantes (comprenant des Données Personnelles) :</p>\n<p>- des données techniques, notamment l’adresse IP (Internet Protocol) utilisée pour connecter votre ordinateur à Internet, vos informations de connexion, le type de navigateur que vous utilisez et sa version, les paramètres de fuseau horaire, les types de modules externes de votre navigateur et leurs versions, le système et la plateforme d’exploitation ;</p>\n<p>- des données concernant votre visite, notamment l’adresse URL complète, le parcours de navigation jusqu’à, dans et à partir de notre site (comprenant la date et l’heure), les produits que vous avez vus ou recherchés, le temps de réponse des pages, les erreurs de téléchargement, la durée des visites sur certaines pages, les données d’interaction de page (telles que le défilement, les clics et les pointages de la souris sur l’image) ainsi que les méthodes utilisées pour naviguer à partir de la page.</p>\n<p>Le caractère obligatoire ou facultatif des données vous est signalé lors de la collecte par un astérisque.</p>\n<p>Sachez que certaines données sont collectées automatiquement du fait de vos actions sur le site. Le traitement de vos données pour vous faire bénéficier d’un service optimal.<br>Nous traitons vos Données Personnelles conformément à la loi en vigueur pour les finalités suivantes :</p>\n<p>- organiser ou nous aider à coordonner les événements promotionnels et leurs activations.<br>- organiser des enquêtes de satisfaction.<br>- pour répondre à toutes questions ou vous fournir des informations, des produits ou des services que vous avez demandés notamment au regard de notre assistance d’utilisateurs.<br>- pour gérer nos comptes et nos dossiers.<br>- pour gérer notre Site Internet et nous aider à améliorer nos produits et services.<br>- pour prévenir et détecter les fraudes, notamment les malwares (malicious softwares ou logiciels malveillants) ainsi que tout abus d’utilisation de notre Site.<br>- pour gérer les incidents de sécurité.<br>- pour mener à bien nos obligations découlant d’un contrat conclu entre vous et nous.<br>- pour effectuer des recherches et des analyses.<br>- pour faciliter votre accès et votre utilisation de notre Site.<br>- pour la gestion du fonctionnement de notre Site et son optimisation.<br>- pour les opérations de vérification, d’identification et d’authentification des données transmises par les utilisateurs.<br>- pour personnaliser votre expérience sur le Site et pour nous permettre de proposer le type de contenu et d’offres de produits le mieux adapté.<br>- pour gérer les éventuels litiges avec les utilisateurs.<br>- pour se conformer à la législation en vigueur, aux règlements et aux décisions de justice.</p>\n<p>Si vous y avez souscrit (notamment en acceptant votre inscription dans la mailing-list), nous traitons également vos Données Personnelles pour vous envoyer des informations sur :</p>\n<p>- des lancements de produits,<br>- des offres spéciales,<br>- des ventes et informations promotionnelles,<br>- des événements.</p>\n<p>Veuillez noter que nous associons également les Données Personnelles que vous nous avez soumises sur notre Site avec d’autres données personnelles vous concernant que l’éditeur peut avoir obtenues par d’autres moyens.</p>\n<p><strong>1.4</strong> Vos données personnelles sont conservées le temps nécessaire à l’accomplissement de l’objectif poursuivi lors de leur collecte c’est-à-dire 36 mois à compter de votre dernier acte d’achat, de votre dernière communication auprès de l’éditeur, ou de la date de fin de vos relations contractuelles avec l’éditeur (la dernière de ces dates étant chronologiquement retenue).</p>\n<p>Vos données seront ensuite archivées avec un accès restreint aux seuls cas de défense des droits de l’éditeur et de demande de l’administration ou de juridiction pour une durée supplémentaire et jusqu’à l’acquisition de la prescription (sauf pour les actions, demandes ou procédures en cours). La durée de prescription en matière consumériste est de 3 ans. Elle est de 10 ans dans les autres matières.</p>\n<p>Passées ces dates, vos données seront ensuite supprimées dans le cadre de l’activité du site web.</p>\n<p><strong>1.5</strong> Le traitement des données personnelles est essentiellement destiné au responsable du site web. Plus spécialement, le site web et son responsable ne divulguent pas, ne vendent pas vos Données Personnelles et seules les personnes dûment autorisées au sein de notre société auront accès à vos Données Personnelles dans la mesure nécessaire et pour les buts mentionnés ci-dessus.</p>\n<p>Toutefois, nous pouvons également être amenés à communiquer vos Données Personnelles à des tiers :</p>\n<p>- avec des fournisseurs de services tiers qui traitent vos Données Personnelles conformément aux buts énoncés ci-dessus ou aux fins auxquelles vous avez consenti</p>\n<p>- plus spécifiquement lorsque notre Site recourt aux services de prestataires pour fournir l’assistance utilisateurs, la publicité et les services de paiement.</p>\n<p>Ces prestataires disposent d’un accès limité aux données de l’utilisateur, dans le cadre de l’exécution de ces prestations, et ont une obligation contractuelle de les utiliser en conformité avec les dispositions de la réglementation applicable en matière protection des données à caractère personnel,</p>\n<p>- lorsque vous publiez, dans les zones de commentaires libres d’un Site internet, des informations accessibles à d’autres internautes,</p>\n<p>- lorsque vous autorisez le site web d’un tiers à accéder à ses données</p>\n<p>- lorsque cela est nécessaire pour protéger la sécurité ou l’intégrité de nos bases de données ou de notre Site</p>\n<p>- lorsque cela est nécessaire dans le cadre d’une procédure judiciaire et pour prendre des précautions contre une mise en oeuvre de responsabilité</p>\n<p>- en cas de vente, de fusion, de réorganisation, de changement de forme juridique, de dissolution ou tout événement similaire et/ou à un successeur potentiel ou réel, lorsque la loi en vigueur nous y autorise,</p>\n<p>- lorsque la loi en vigueur l’exige. Par exemple, si la loi l’exige, nous pouvons effectuer la transmission de données pour donner suite aux réclamations présentées contre l’éditeur et nous conformer aux procédures administratives et judiciaires.</p>\n<p>Toutefois, en tout état de cause internet n’est pas un environnement parfaitement sécurisé et le site web et son responsable Lorang ne peuvent pas garantir la sécurité de la transmission ou du stockage des informations sur internet.</p>\n<h2>ARTICLE 2 : MISE A JOUR</h2>\n<p>La présente charte peut être mise à jour périodiquement et sans préavis. Si vous n’êtes pas d’accord avec les termes de la nouvelle rédaction de la charte de protection des données à caractère personnel, vous avez la possibilité de faire usage de vos droits rappelés ci-dessus, et notamment votre droit à l’effacement et à la suppression, dans le respect des conditions légales, réglementaires et contractuelles.</p>\n<h2>ARTICLE 3 : DROITS DE LA PERSONNE CONCERNEE</h2>\n<p><strong>3.1</strong> La personne concernée par le traitement des données personnelles dispose de la possibilité de demander confirmation du traitement ou non de ses données, et le cas échéant d’un droit d’accès à ses données personnelles, et de copie dans le cadre des dispositions légales.</p>\n<p><strong>3.2</strong> La personne concernée dispose d’un droit de rectification des données personnelles inexactes dans les meilleurs délais. Elle peut également compléter les données jusqu’alors incomplètes.</p>\n<p><strong>3.3</strong> Un droit à l’effacement des données personnelles est conféré à la personne concernée. Cette demande doit toutefois être légitime et elle ne peut se faire que dans certaines conditions légales et réglementaires, afin de préserver vos droits et ceux de la société Étude d’Avocats LW LEGIS.</p>\n<p>Un droit à l’effacement est également octroyé si la personne concernée retire son consentement ou s’oppose au traitement à des fins de prospection ou pour des raisons relatives à sa situation particulière.</p>\n<p>Ce droit peut également être exercé en cas de traitement illicite des données ou dans le respect d’une obligation légale prévu par le droit de l’Union ou de l’État membre.</p>\n<p><strong>3.4</strong> La personne concernée a le droit de demander la limitation du traitement de ses données si elle conteste l’exactitude des données, pour une durée permettant à la société Étude d’Avocats LW LEGIS d’en vérifier l’exactitude.</p>\n<p><strong>3.5</strong> Si elle remplit les conditions légales, la personne concernée bénéficie d’un droit de demander la communication de ses données à caractère personnel dans un format courant, structuré, couramment utilisé et lisible par machine.</p>\n<p>Si elle remplit les conditions légales, la personne concernée peut également demander le transfert direct des données à caractère personnel de la société Étude d’Avocats LW LEGIS à un autre responsable du traitement.</p>\n<p><strong>3.6</strong> Le droit d’opposition et de retrait de consentement<br>Vous avez le droit de vous opposer à la fourniture de vos données personnelles. Dans ce cas, votre expérience avec le site et la Société Étude d’Avocats LW LEGIS risque d’être limitée voire inexistante si vos données personnelles demandées sont nécessaires à la relation entre la Société et vous ; ou votre demande risque de ne pas pouvoir être traitée, pour les mêmes raisons. Vous avez le droit, pour l’avenir, de revenir sur votre consentement à ce que vos données personnelles soient traitées, avec les mêmes conséquences éventuelles que celles exprimées aux présents articles.</p>\n<p>Si vous retirez certains consentements, vous pourriez ne pas être en mesure d’utiliser l’intégralité des fonctions de ce Site Internet ou d’autres Sites ou services en ligne.</p>\n<p><strong>3.7</strong> Dans les limites prévues par la législation en vigueur, la personne concernée bénéficie donc des différents droits concernant la protection de ses données personnelles, à savoir :</p>\n<p>- le droit d’accès<br>- le droit à la rectification<br>- le droit à l’effacement<br>- le droit à la limitation<br>- le droit à la portabilité<br>- le droit à l’opposition et au de retrait de consentement au traitement des données à caractère personnel</p>\n<p>Ces droits peuvent être exercés directement par mail à l’adresse suivante (dans ce cas, conformément à la réglementation, votre demande devra être accompagnée de la copie lisible et compréhensible d’un justificatif d’identité officiel, en cours de validité) :</p>\n<p><a href=\"mailto:contact@cabinet-avocats-lorang.com\">contact@cabinet-avocats-lorang.com</a></p>\n<p>Si vous considérez que le traitement de données à caractère personnel vous concernant ne respecte pas la règlementation vous disposez de la possibilité :<br>- de contacter le Délégué à la protection des données de la société Étude d’Avocats LW LEGIS, Lorang, à l’adresse contact@cabinet-avocats-lorang.com<br>- d’introduire une réclamation auprès de la Commission Nationale de l’Informatique et des Libertés (CNIL www.cnil.fr). Si vous souhaitez obtenir des informations supplémentaires sur vos droits, vous pouvez également vous rendre sur le site internet de la CNIL.</p>\n<h2>Commentaires</h2>\n<p>Quand vous laissez un commentaire sur notre site web, les données inscrites dans le formulaire de commentaire sont enregistrées dans une base de données. Après validation de votre commentaire, celui-ci sera publié sur le site.</p>\n<h2>Formulaires de contact</h2>\n<p>Lorsque vous nous envoyez un message par la page Contact de notre site, nous vous demandons les coordonnées nécessaires pour pouvoir vous répondre. Ces données ne serviront pas à d’autres usages. Ces données nous sont envoyées par e-mail. Elles ne sont pas conservées sur le site internet. Étude d’Avocats LW LEGIS est seul à avoir accès à ces données au moyen de la messagerie électronique.</p>\n<h2>Newsletter</h2>\n<p>Vous avez la possibilité de vous abonner à notre newsletter depuis notre site web. Le processus d’abonnement est « double opt’in », c’est-à-dire que lorsque vous vous abonnez à notre newsletter, vous recevez un e-mail contenant un lien pour confirmer votre abonnement. Cela nous garantit que vous avez bien demandé à vous abonner et que personne d’autre n’a enregistré votre adresse e-mail à votre place. Notre newsletter est susceptible d’être gérée sur une plateforme externe (ex : MailChimp, Sendinblue). La société Étude d’Avocats LW LEGIS est la seule à avoir accès aux coordonnées des contacts enregistrés dans les listes de diffusion. Vous pouvez vous désabonner à tout instant par simple clic sur le lien figurant en bas de toutes nos newsletters. Vous disposez également d’un droit d’accès, de rectification et d’effacement. Vous pouvez exercer ce droit en nous en faisant la demande par tout moyen de contact à votre convenance.</p>\n<h2>Contenu embarqué depuis d’autres sites</h2>\n<p>Les articles de ce site peuvent inclure des contenus intégrés hébergés sur d’autres sites (par exemple des vidéos, images, articles…). Le contenu intégré depuis d’autres sites se comporte de la même manière que si le visiteur se rendait sur cet autre site. Par exemples ces sites web tiers pourraient collecter des données sur vous, utiliser des cookies, embarquer des outils de suivis tiers, suivre vos interactions avec ces contenus embarqués si vous disposez d’un compte connecté sur leur site web. Ces sites web sont responsables de la collecte et du traitement des données à partir des contenus qu’ils hébergent.</p>\n<h2>Statistiques et mesures d’audience</h2>\n<p>Ce site utilise Google Analytics pour collecter des données statistiques telles que pages visitées, localisation de l’internaute, heure de visite, etc. Nous n’avons accès qu’aux données habituellement mises à disposition par Google Analytics sur son interface. Elles sont totalement anonymes : il nous est impossible d’identifier les personnes à partir des rapports à notre disposition.</p>\n<h2>Utilisation et transmission de vos données personnelles</h2>\n<p>Vos données personnelles ne seront utilisées que pour les usages pour lesquels vous nous les communiquez. Elles ne seront pas transmises à des tiers.</p>\n<h2>Durées de stockage de vos données</h2>\n<p>Si vous laissez un commentaire, le commentaire et ses métadonnées sont conservés indéfiniment. Les autres données sont conservées le temps nécessaire aux traitements pour lesquels vous nous les avez communiquées et/ou pour lesquels vous nous avez donné votre consentement explicite.</p>\n<h2>Les droits que vous avez sur vos données</h2>\n<p>Si vous êtes abonné(e) à notre newsletter ou si vous avez laissé des commentaires sur le site, vous pouvez demander à recevoir un fichier contenant toutes les données personnelles que nous possédons à votre sujet, incluant celles que vous nous avez fournies. Vous pouvez également demander la suppression des données personnelles vous concernant. Cela ne prend pas en compte les données stockées à des fins administratives, légales ou pour des raisons de sécurité, ni les données anonymes des statistiques. Ces actions seront réalisées dans les meilleurs délais, sous réserve de faisabilité technique.</p>\n"}'::jsonb, 'veroeffentlicht'),
  ('cookies', '{"fr":"Les Cookies"}'::jsonb, '{}'::jsonb, '[]'::jsonb, '{"fr":"\n<h2>Cookies</h2>\n<p>Les cookies sont des petits fichiers textes stockés dans votre navigateur lorsque vous consultez notre site sous réserve du paramétrage de votre navigateur et qui vont être utilisés pour reconnaître votre terminal lorsque vous vous connectez à notre site afin : d’établir des statistiques et comptages de fréquentation et d’utilisation des diverses rubriques et contenus de notre site afin de réaliser des études pour en améliorer le contenu ; d’adapter du contenu publicitaire à vos centres d’intérêts et, éventuellement, votre localité, qui résultent des données de navigation de votre terminal parmi les rubriques de notre site sans que nous n’ayons de données personnelles permettant de vous identifier ou de vous contacter directement.</p>\n<h2>Les cookies tiers</h2>\n<p>Lorsque vous accédez à notre site, un ou plusieurs cookies de sociétés partenaires (« cookies tiers ») sont susceptibles d’être placés dans votre terminal. Ces cookies tiers ont pour finalité d’identifier vos centres d’intérêt au travers des produits consultés sur notre site et de collecter des données de navigation afin de personnaliser l’offre publicitaire qui vous est adressée en dehors de nos sites.</p>\n<p>Nous veillons à ce que les sociétés partenaires acceptent de traiter les informations collectées sur nos sites dans le respect de la loi «Informatique et Libertés » du 6 janvier 1978 et s’engagent à mettre en œuvre des mesures appropriées de sécurisation et de protection de la confidentialité des données.<br>Les cookies intégrés à des applications tierces sur notre site</p>\n<p>Nous sommes susceptibles d’inclure une application informatique tierce dans certaines des fonctionnalités de notre site, permettant le partage de contenus par les utilisateurs de notre site, tels que les boutons « Partager » ou « J’aime » de Facebook, ou les boutons « Twitter », « LinkedIn », etc.</p>\n<p>Le réseau social fournissant l’application est susceptible de vous identifier grâce à ses propres cookies, même si vous n’avez pas utilisé ses boutons lors de votre consultation de notre site, du seul fait que vous soyez connecté à votre compte utilisateur sur votre terminal auprès du réseau social concerné.</p>\n<p>Nous n’avons aucun contrôle sur le processus employé par les réseaux sociaux pour collecter ces informations et vous invitons à consulter les politiques de confidentialité de ces derniers.</p>\n"}'::jsonb, 'veroeffentlicht'),
  ('conditions', '{"fr":"Conditions générales du cabinet d’avocats LW Legis","en":"General Terms and Conditions of The Law Firm LW LEGIS"}'::jsonb, '{}'::jsonb, '[]'::jsonb, '{"fr":"\n<h2>Article 1 - Applicabilité des Conditions Générales</h2>\n<p>Les conditions générales telles que publiées sur le présent site gouvernent les relations entre le cabinet d’avocats et ses clients.<br>Tout mandat donné au cabinet LW Legis sera régi par celles-ci qui sont supposées être connues et acceptées par le client dans leur intégralité et sans réserves.<br>En cas de conflit ou de contradiction entre les présentes conditions et celles du client seules les présentes conditions seront applicables.<br>Le cabinet LW Legis se réserve la possibilité de modifier celle-ci.<br>Les modifications seront applicables même aux mandats en cours à partir de leur date de publication sur le site.</p>\n<h2>Article 2 - Forme du mandat</h2>\n<p>Le mandat donné au cabinet LW Legis n’est pas soumis à une condition de forme particulière tel un écrit contractuel signé par les deux parties.<br>Le mandat peut résulter d’une instruction orale ou d’une demande écrite de la part d’un client.<br>De façon générale toute demande adressée au cabinet en vue de l’obtention d’un renseignement portant sur une question de droit constitue un mandat.</p>\n<h2>Article 3 - Acceptation du mandat</h2>\n<p>Le cabinet LW Legis est libre de ne pas accepter un mandat sans avoir à justifier des causes de son refus.<br>Le cabinet est également autorisé à déposer un mandat sans avoir à en justifier et sans que ce dépôt n’ouvre dans le chef du client un quelconque droit à indemnisation.</p>\n<h2>Article 4 - Honoraires</h2>\n<p>Les honoraires de l’avocat sont libres et il n’existe pas de barème de tarification.</p>\n<p>La profession d’avocat est régulée par la loi du 10 août 1991 dont l’article 38 détermine les critères de fixation des honoraires qui sont :</p>\n<p>L’importance de l’affaire<br>Le degré de difficulté de celle-ci<br>Le résultat obtenu<br>La situation de fortune du client</p>\n<p>Le règlement intérieur du barreau précise que sont à prendre également en compte.</p>\n<p>Le travail fourni par l’avocat (Heures passées)<br>La notoriété de l’avocat<br>L’expérience professionnelle de l’avocat</p>\n<p>Les honoraires sont redus dès la première consultation quelle que soit sa forme ou son support.<br>L’avocat étant tenu d’une obligation de moyen et non de résultat les honoraires sont payables quelle que soit l’issue du litige.<br>Un honoraire de succès est facturé en fonction du résultat obtenu.<br>En cas de mandat donné par un professionnel pour le compte d’un de ses clients, le professionnel sera personnellement tenu du règlement des devoirs et prestations qu’il aura sollicités auprès du cabinet sauf règlement effectif desdites prestations par son client.<br>Une estimation purement informative des honoraires peut être donnée dans la mesure du possible. Celle-ci ne se substitue pas au décompte définitif des frais et honoraires établi lors de la clôture du dossier.<br>Les honoraires sont soumis de par la loi à une TVA dont le taux actuel est de 16%.</p>\n<h2>Article 5 - Frais et débours</h2>\n<p>En dehors des honoraires le Client réglera les différents frais engagés dans le cadre du règlement de son dossier notamment : frais de secrétariat, de procédure, de publication et d’enregistrement, d’huissier, d’expertises, frais de déplacement et d’hébergement etc</p>\n<h2>Article 6 - Provision sur frais et honoraires et facturation</h2>\n<p>Le cabinet LW Legis est autorisé à demander au client le règlement d’une provision au début et/ou en cours du traitement du dossier.<br>En cas de non règlement de cette provision le cabinet est autorisé à arrêter toute prestation sans que sa responsabilité ne puisse être engagée de ce chef.<br>Toute facture émanant du cabinet est réglable dans le délai de huitaine.<br>En cas de deux rappels restés infructueux, le cabinet sera autorisé à facturer des intérêts de retard à partir de la date d’échéance des factures au taux directeur de la banque centrale majoré de deux pour cents.</p>\n<h2>Article 7.1 - Obligations de l’avocat et secret professionnel</h2>\n<p>L’avocat s’engage à traiter les dossiers qui lui sont confiés avec diligence.<br>Toutes les informations qui lui sont délivrées sont couvertes par le secret professionnel.</p>\n<h2>Article 7.2 - Obligations du client</h2>\n<p>Le client s’engage à collaborer de façon loyale avec l’avocat. Particulièrement il le renseignera de façon sincère sur sa situation personnelle et sur les éléments du dossier. Il s’engage à transmettre à l’avocat les renseignements, pièces et documents que celui-ci lui réclame pour le traitement de son dossier. Il s’engage à donner une suite diligente à toute demande de rémunération ou de payement de frais.</p>\n<h2>Article 8 - Archivage</h2>\n<p>Après clôture du dossier l’avocat a une obligation d’archivage des documents pour une période de 5 ans.<br>Au delà de cette période, l’avocat est autorisé à les détruire sauf à ce que le client ait pris RV pour récupérer les pièces de son dossier.</p>\n<h2>Article 9 - Blanchiment d’argent</h2>\n<p>Le cabinet d’avocat est soumis à la législation luxembourgeoise en matière de blanchiment d’argent.<br>Dans tout dossier de consultation en vue de la mise en place ou la transformation de structures juridiques, de gestion de fonds, de structuration fiscale et autres activités prévues par la législation le client devra se soumettre aux demandes de renseignement adressées par le cabinet.<br>La non délivrance par le client des documents requis en la matière peut entraîner une déclaration de soupçon aux autorités.</p>\n<h2>Article 10 - Responsabilité</h2>\n<p>L’avocat est tenu d’une obligation de moyen. Le quantum de sa responsabilité est limité au montant des honoraires encaissés.</p>\n<h2>Article 11 - Propriété Intellectuelle</h2>\n<p>Toute consultation, note, avis émanant du cabinet sont protégés par les droits de propriété intellectuelle. Ils ne sauraient être transmis à des tierces personnes sans l’autorisation préalable du cabinet.<br>L’utilisation non autorisée des renseignements y contenus est prohibée et le cabinet ne saurait voir engager sa responsabilité à cet égard.</p>\n<h2>Article 12 - Juridiction applicable et loi compétente</h2>\n<p>Les relations entre le cabinet LW Legis et ses clients sont exclusivement régies par les textes légaux ou réglementaires luxembourgeois applicables à l’exception de toute autre législation étrangère applicable.<br>Seuls les tribunaux luxembourgeois sont compétents à l’exception de toute juridiction étrangère.<br>Les clients dont l’adresse ou le siège sont situés en dehors du Luxembourg acceptent expressément la compétence juridictionnelle des juridictions luxembourgeoises pour tout litige né de l’interprétation ou de l’exécution de la présente convention.</p>\n<p>Version du 15 mai 2023</p>\n","en":"\n<h2>Rule 1 - Applicability of the General Conditions</h2>\n<p>The terms and conditions as published on this site govern the relationship between the law firm and its clients. Any mandate given to LW will be governed by these terms, which are assumed to be known and accepted by the client in their entirety and without reservation. In the event of any conflict or contradiction between these terms and those of the customer, only these terms and conditions shall apply. LW reserves the right to change this. The amendments will apply even to current mandates from the date they are posted on the site</p>\n<h2>Rule 2 - Form of mandate</h2>\n<p>The mandate given to LW is not subject to any special formal requirement such as a written contract signed by both parties. The mandate may result from an oral instruction or a written request by a client. Generally, any request to the firm for information on a matter of law is a warrant.</p>\n<h2>Rule 3 - Acceptance of the mandate</h2>\n<p>LW is free to refuse a warrant without having to give reasons for its refusal. The firm is also entitled to file a warrant without having to justify it and without giving rise to any right to compensation on the part of the client.</p>\n<h2>Rule 4 - Fees</h2>\n<p>The lawyer’s fees are free and there is no fee structure.</p>\n<p>The legal profession is regulated by the Law of 10 August 1991, article 38 of which lays down the criteria for setting fees, which are :</p>\n<p>The importance of the case<br>The difficulty of the case<br>The result obtained<br>The financial situation of the client</p>\n<p>The rules of procedure of the bar specify that the following are also to be taken into account.</p>\n<p>The work done by the lawyer (Hours worked)<br>The reputation of the lawyer<br>The professional experience of the lawyer</p>\n<p>The fees are reduced from the first consultation, regardless of its form or medium. As the lawyer is bound by an obligation of means and not of result, fees are payable regardless of the outcome of the dispute. A success fee is charged based on the result obtained. In the event of a mandate given by a professional on behalf of one of its clients, the professional will be personally liable for the payment of the duties and services that he has requested from the firm unless the said services are actually paid by his client. Where possible, a purely informative estimate of fees may be provided. This does not replace the final statement of costs and fees drawn up when the file is closed. The fees are subject by law to VAT at the current rate of 16%.</p>\n<h2>Rule 5 - Costs and disbursements</h2>\n<p>In addition to the fees, the Client will pay the various expenses incurred as part of the settlement of his case, in particular: secretarial, procedural, publication and registration costs, bailiff, expert opinions, travel and accommodation costs, etc.</p>\n<h2>Rule 6 - Provision for fees and charges and invoicing</h2>\n<p>LW law firm is entitled to ask the client to pay a deposit at the beginning and/or during the processing of the case. In the event of non-payment of this provision, the firm is entitled to discontinue any service without incurring any liability. Any invoice from the firm is payable within eight weeks. In the event of two unsuccessful recalls, the firm will be allowed to charge late interest from the due date of the invoices at the central bank’s key interest rate plus two per cent.</p>\n<h2>Rule 7.1 - Obligations of counsel and professional secrecy</h2>\n<p>The lawyer undertakes to deal with the files entrusted to him with diligence.<br>All information provided to him shall be covered by professional secrecy.</p>\n<h2>Rule 7.2 - Obligations of the client</h2>\n<p>The client undertakes to cooperate loyally with the lawyer. In particular, he will provide him with honest information about his personal situation and the facts of the case. He undertakes to transmit to the lawyer the information, documents and documents requested by the lawyer for the processing of his case. He undertakes to act expeditiously on any request for remuneration or payment of costs.</p>\n<h2>Rule 8 - Archiving</h2>\n<p>After the case is closed, the lawyer has an obligation to archive the documents for a period of 5 years. After this period, the lawyer is authorized to destroy them unless the client has taken RV to retrieve the exhibits from his file.</p>\n<h2>Rule 9 - Money laundering</h2>\n<p>The law firm is subject to Luxembourg law on money laundering.<br>In any consultation file with a view to the establishment or transformation of legal structures, fund management, tax structuring and other activities provided for by the law, the client must submit to the requests for information addressed by the firm. Failure by the client to issue the required documents may result in a declaration of suspicion to the authorities.</p>\n<h2>Rule 10 - Responsabilité</h2>\n<p>The lawyer is bound by an obligation of means. The quantum of its liability is limited to the amount of the fees collected.</p>\n<h2>Rule 11 - Intellectual Property</h2>\n<p>All consultations, notes, opinions from the firm are protected by intellectual property rights. They may not be passed on to third parties without the firm’s prior consent.<br>Unauthorized use of the information contained therein is prohibited and the firm cannot be held liable in this regard.</p>\n<h2>Rule 12 - Applicable jurisdiction and competent law</h2>\n<p>The relations between LW and its clients are governed exclusively by the applicable laws or regulations of Luxembourg, with the exception of any other applicable foreign legislation.<br>Only the Luxembourg courts have jurisdiction, with the exception of any foreign court.<br>Customers whose address or registered office is located outside Luxembourg expressly accept the jurisdiction of the courts of Luxembourg for any dispute arising out of the interpretation or execution of this Agreement.</p>\n<p>Version of 15 May 2023</p>\n"}'::jsonb, 'veroeffentlicht')
