  ('accueil', '{"fr":"Cabinet d’avocats au Luxembourg – Étude d’Avocats LW LEGIS","en":"Law firm in Luxembourg – The Law Firm LW LEGIS"}'::jsonb, '{"fr":"L’étude d’Avocats LW LEGIS est spécialisée en droit des sociétés au Luxembourg et en fiscalité internationale, elle conseille ses clients dans les domaines de la constitution et de la gestion de structures sociétaires adaptées à leurs besoins au Grand-Duché du Luxembourg.","en":"The Law Firm LW LEGIS specialises in Real Estate and Patrimonial law, Luxembourg Company Law and International Taxation. We advise our entrepreneur clients in the areas of constitution, management and domiciliation of corporate structures adapted to their needs in the Grand Duchy of Luxembourg."}'::jsonb, false),
  ('avocats', '{"fr":"Les avocats de l’étude LW LEGIS","en":"The lawyers from the Law Firm LW LEGIS"}'::jsonb, '{"fr":"Le cabinet est composé d’avocats expérimentés sous la responsabilité de Maître Alain LORANG. Flexibilité, compétences transversales, conseils experts."}'::jsonb, false),
  ('activites', '{"fr":"Les activités de notre cabinet d’avocats au Luxembourg","en":"The activities of our law firm in Luxembourg"}'::jsonb, '{"fr":"Le cabinet dispose d’une large palette de compétences en droit luxembourgeois, français et européen : dépôts, brevets, marques, banque, finance, domiciliation des entreprises, assurance et indemnisation, recouvrement de créances.","en":"The firm has a wide range of skills in Luxembourg, French and European law: deposits, patents, trademarks, banking, finance, domiciliation of companies, insurance and compensation, debt collection."}'::jsonb, false),
  ('dossiers', '{"fr":"Les dossiers thématiques de l’étude d’avocats LW LEGIS","en":"Thematic files – The Law Firm LW LEGIS"}'::jsonb, '{"fr":"Immobilier, économie, fiscalité, finance, recouvrement, créance, conformité avec la loi, procédure anti-blanchiment : un cabinet d’expertise en droit luxembourgeois.","en":"Real estate, economy, taxation, finance, recovery, debt, compliance with the law, anti-money laundering procedure: an expertise firm in Luxembourg law."}'::jsonb, false),
